MOD = 10 ** 9 + 7

def countWaysToTravelCities(N: int, K: int) -> int:
    # 序列满足 c[t+1] >= 2*c[t]，最小的序列是 1,2,4,...,2^(N-1)
    if N <= 0 or (1 << (N - 1)) > K:
        return 0
    f = [0] + [1] * K          # f[c]：当前长度、以城市 c 结尾的方案数
    for _ in range(N - 1):
        pref = [0] * (K + 1)
        for c in range(1, K + 1):
            pref[c] = (pref[c - 1] + f[c]) % MOD
        # 上一个城市 p 必须满足 2p <= c，即 p <= c // 2
        f = [0] + [pref[c // 2] for c in range(1, K + 1)]
    return sum(f) % MOD
